<?php
/** آرشیو موضوعی یادداشت‌های شبکه تحلیلگران. */
if ( ! defined( 'ABSPATH' ) ) { exit; }
$term = get_queried_object();
if ( ! $term instanceof WP_Term ) { get_template_part( 'archive-analyst_post' ); return; }
get_header();
$paged = max( 1, (int) get_query_var( 'paged', 1 ) );
$active_sort = sanitize_key( wp_unslash( $_GET['sort'] ?? 'date' ) );
$active_search = sanitize_text_field( wp_unslash( $_GET['q'] ?? '' ) );
$term_url = get_term_link( $term );
$term_url = is_wp_error( $term_url ) ? get_post_type_archive_link( 'analyst_post' ) : $term_url;
$archive_data = function_exists( 'revayat_get_archive_data' ) ? revayat_get_archive_data( 'analyst_post', array( 'paged' => $paged, 'field' => $term->slug, 'sort' => $active_sort, 'search' => $active_search ) ) : array();
$items = $archive_data['items'] ?? array();
$total_posts = absint( $archive_data['total_posts'] ?? $term->count );
$max_pages = max( 1, absint( $archive_data['max_pages'] ?? 1 ) );
$sort_options = $archive_data['filter_options']['sorts'] ?? array();
$field_options = $archive_data['filter_options']['fields'] ?? array();
$people_data = function_exists( 'revayat_get_archive_data' ) ? revayat_get_archive_data( 'person', array( 'field' => $term->slug, 'posts_per_page' => 4, 'paged' => 1 ) ) : array();
$field_people = $people_data['items'] ?? array();
$last_update = ! empty( $items[0]['date'] ) ? $items[0]['date'] : '';
$member_url = is_user_logged_in() ? home_url( '/dashboard/' ) : home_url( '/auth/?tab=register' );
?>
<main id="primary" class="anx-page anx-topic-archive">
	<section class="anx-topic-hero"><div class="container anx-topic-hero__grid"><div><nav class="anx-breadcrumb" aria-label="<?php esc_attr_e( 'مسیر راهنما', 'revayatiran' ); ?>"><a href="<?php echo esc_url( get_post_type_archive_link( 'analyst_post' ) ); ?>"><?php esc_html_e( 'شبکه تحلیلگران', 'revayatiran' ); ?></a><i class="ph ph-caret-left"></i><span><?php esc_html_e( 'موضوعات', 'revayatiran' ); ?></span></nav><span class="anx-eyebrow"><i class="ph ph-chart-bar"></i><?php esc_html_e( 'حوزه تحلیلی', 'revayatiran' ); ?></span><h1><?php echo esc_html( $term->name ); ?></h1><?php if ( $term->description ) : ?><p><?php echo esc_html( $term->description ); ?></p><?php else : ?><p><?php printf( esc_html__( 'تحلیل‌ها و دیدگاه‌های تخصصی منتشرشده در حوزه %s', 'revayatiran' ), esc_html( $term->name ) ); ?></p><?php endif; ?></div><div class="anx-topic-hero__actions"><form role="search" method="get" action="<?php echo esc_url( $term_url ); ?>" class="anx-search"><label class="screen-reader-text" for="anx-topic-search"><?php esc_html_e( 'جستجو در این موضوع', 'revayatiran' ); ?></label><i class="ph ph-magnifying-glass"></i><input id="anx-topic-search" type="search" name="q" maxlength="100" value="<?php echo esc_attr( $active_search ); ?>" placeholder="<?php esc_attr_e( 'جستجوی تحلیل‌ها در این موضوع…', 'revayatiran' ); ?>"><input type="hidden" name="sort" value="<?php echo esc_attr( $active_sort ); ?>"><button type="submit"><?php esc_html_e( 'جستجو', 'revayatiran' ); ?></button></form><dl><div><dt><?php esc_html_e( 'یادداشت‌ها', 'revayatiran' ); ?></dt><dd><?php echo esc_html( revayat_en2fa( $total_posts ) ); ?></dd></div><div><dt><?php esc_html_e( 'تحلیلگران', 'revayatiran' ); ?></dt><dd><?php echo esc_html( revayat_en2fa( absint( $people_data['total_posts'] ?? count( $field_people ) ) ) ); ?></dd></div><div><dt><?php esc_html_e( 'آخرین بروزرسانی', 'revayatiran' ); ?></dt><dd><?php echo $last_update ? esc_html( revayat_en2fa( $last_update ) ) : '—'; ?></dd></div></dl></div></div></section>

	<div class="container anx-layout">
		<section class="anx-feed" aria-labelledby="anx-topic-feed-title"><header class="anx-feed-toolbar"><div class="anx-section-heading"><div><span><?php esc_html_e( 'آرشیو موضوعی', 'revayatiran' ); ?></span><h2 id="anx-topic-feed-title"><?php printf( esc_html__( 'تحلیل‌های %s', 'revayatiran' ), esc_html( $term->name ) ); ?></h2></div><p><?php printf( esc_html__( '%s نتیجه', 'revayatiran' ), esc_html( revayat_en2fa( $total_posts ) ) ); ?></p></div><nav class="anx-sort" aria-label="<?php esc_attr_e( 'مرتب‌سازی یادداشت‌ها', 'revayatiran' ); ?>"><?php foreach ( $sort_options as $sort ) : $sort_url = add_query_arg( array_filter( array( 'q' => $active_search, 'sort' => $sort['slug'] ?? 'date' ) ), $term_url ); ?><a class="<?php echo ! empty( $sort['is_active'] ) ? 'is-active' : ''; ?>" href="<?php echo esc_url( $sort_url ); ?>"><i class="ph ph-<?php echo esc_attr( 'score' === ( $sort['slug'] ?? '' ) ? 'chart-bar' : 'clock' ); ?>"></i><?php echo esc_html( $sort['label'] ?? '' ); ?></a><?php endforeach; ?></nav></header>
			<?php if ( $items ) : ?><div class="anx-feed-list"><?php foreach ( $items as $item ) { get_template_part( 'template-parts/cards/card-analyst', null, array( 'item' => $item, 'variant' => 'grid' ) ); } ?></div><?php if ( $max_pages > 1 ) : ?><nav class="anx-pagination" aria-label="<?php esc_attr_e( 'صفحه‌بندی', 'revayatiran' ); ?>"><?php echo wp_kses_post( paginate_links( array( 'current' => $paged, 'total' => $max_pages, 'prev_text' => '→', 'next_text' => '←' ) ) ); ?></nav><?php endif; else : ?><div class="anx-empty"><i class="ph ph-note-blank"></i><h2><?php esc_html_e( 'یادداشتی در این موضوع وجود ندارد', 'revayatiran' ); ?></h2><a href="<?php echo esc_url( get_post_type_archive_link( 'analyst_post' ) ); ?>"><?php esc_html_e( 'مشاهده همه تحلیل‌ها', 'revayatiran' ); ?></a></div><?php endif; ?>
		</section>
		<aside class="anx-sidebar"><section class="anx-side-card"><header><i class="ph ph-info"></i><h2><?php esc_html_e( 'درباره این موضوع', 'revayatiran' ); ?></h2></header><p><?php echo esc_html( $term->description ?: sprintf( __( 'این صفحه مجموعه یادداشت‌های منتشرشده در حوزه %s را گردآوری می‌کند.', 'revayatiran' ), $term->name ) ); ?></p><?php if ( $last_update ) : ?><small><i class="ph ph-calendar"></i><?php printf( esc_html__( 'آخرین بروزرسانی: %s', 'revayatiran' ), esc_html( revayat_en2fa( $last_update ) ) ); ?></small><?php endif; ?></section>
			<section class="anx-side-card"><header><i class="ph ph-stack"></i><h2><?php esc_html_e( 'حوزه‌های مرتبط', 'revayatiran' ); ?></h2></header><div class="anx-related-fields"><?php foreach ( $field_options as $field ) : if ( 'all' === ( $field['slug'] ?? 'all' ) || $term->slug === ( $field['slug'] ?? '' ) ) { continue; } ?><a href="<?php echo esc_url( $field['url'] ?? '' ); ?>"><span><?php echo esc_html( $field['label'] ?? '' ); ?></span><small><?php echo esc_html( revayat_en2fa( $field['count'] ?? 0 ) ); ?></small></a><?php endforeach; ?></div></section>
			<section class="anx-side-card"><header><i class="ph ph-users"></i><h2><?php esc_html_e( 'تحلیلگران این حوزه', 'revayatiran' ); ?></h2></header><?php if ( $field_people ) : ?><ul class="anx-related-people"><?php foreach ( $field_people as $person ) : ?><li><a href="<?php echo esc_url( $person['url'] ?? $person['permalink'] ?? '' ); ?>"><?php if ( ! empty( $person['media']['url'] ) ) : ?><img src="<?php echo esc_url( $person['media']['url'] ); ?>" alt="" loading="lazy"><?php else : ?><span><i class="ph ph-user"></i></span><?php endif; ?><span><strong><?php echo esc_html( $person['title'] ?? '' ); ?></strong><small><?php echo esc_html( $person['meta']['role_title'] ?? '' ); ?></small></span></a></li><?php endforeach; ?></ul><?php else : ?><p class="anx-side-empty"><?php esc_html_e( 'هنوز تحلیلگری به این حوزه متصل نشده است.', 'revayatiran' ); ?></p><?php endif; ?></section>
			<section class="anx-side-card anx-join-card"><i class="ph ph-users-three"></i><h2><?php esc_html_e( 'عضو شبکه تحلیلگران شوید', 'revayatiran' ); ?></h2><p><?php esc_html_e( 'تجربه و دیدگاه تخصصی خود را با جامعه روایت ایران به اشتراک بگذارید.', 'revayatiran' ); ?></p><a href="<?php echo esc_url( $member_url ); ?>"><?php echo is_user_logged_in() ? esc_html__( 'ورود به پنل شخصی', 'revayatiran' ) : esc_html__( 'درخواست عضویت', 'revayatiran' ); ?><i class="ph ph-arrow-left"></i></a></section>
		</aside>
	</div>
</main>
<?php get_footer();
